namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Auto-detection failed: no IChatClient registration found in
    /// AppHost or agent projects. Wire your client manually.
    /// </summary>
    public static IChatClient Create() =>
        throw new NotImplementedException(
            "Wire your IChatClient here. See https://learn.microsoft.com/en-us/dotnet/ai/microsoft-extensions-ai");
}

namespace MyApp.Evals.Tests;

/// <summary>
/// Returns canned responses when EVAL_USE_REAL_AGENT is unset.
/// Allows NLP evaluators (Words/BLEU/GLEU/F1) to run without credentials.
/// </summary>
internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var userMsg = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";
        var stub = $"This is a stub response for: {userMsg}";
        return Task.FromResult(new ChatResponse(new ChatMessage(ChatRole.Assistant, stub)));
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
        => throw new NotSupportedException("Stub does not support streaming.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

namespace MyApp.Evals.Tests;

internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveJudgeClient(IChatClient agent)
    {
        var judgeDeploy = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (!string.IsNullOrEmpty(judgeDeploy))
        {
            // Separate judge model — user must wire connection string for this deployment.
            return AgentChatClientFactory.Create();
        }

        return agent;
    }
}

using System.Text.Json;

namespace MyApp.Evals.Tests;

public record GoldenItem(string Id, string UserMessage, string? ReferenceResponse, string? Context, string[]? ExpectedTraits);

internal static class GoldenLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<GoldenItem> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<List<GoldenItem>>(json, s_options) ?? new();
    }
}

internal static class RubricLoader
{
    public static string SystemPrompt()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");
        return File.Exists(path) ? File.ReadAllText(path) : "You are a helpful assistant.";
    }
}

namespace MyApp.Evals.Tests;

[TestClass]
public sealed class QualityTests
{
    private static ReportingConfiguration s_reporting = null!;

    [ClassInitialize]
    public static void Init(TestContext _) =>
        s_reporting = ReportingConfig.ForQuality();

    public static IEnumerable<object[]> Golden() =>
        GoldenLoader.Load().Select(g => new object[] { g });

    [TestMethod]
    [DynamicData(nameof(Golden), DynamicDataSourceType.Method)]
    public async Task Evaluate(GoldenItem g)
    {
        var scenarioName = $"{nameof(QualityTests)}.{g.Id}";
        await using var run = await s_reporting.CreateScenarioRunAsync(scenarioName);

        var agent = string.IsNullOrEmpty(
            Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME"))
                ? run.ChatConfiguration!.ChatClient
                : Wire.ResolveAgentClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, RubricLoader.SystemPrompt()),
            new(ChatRole.User, g.UserMessage),
        };
        var response = await agent.GetResponseAsync(messages);

        var contexts = new List<EvaluationContext>();
        if (!string.IsNullOrEmpty(g.ReferenceResponse))
        {
            contexts.Add(new BLEUEvaluatorContext(new[] { g.ReferenceResponse }));
            contexts.Add(new GLEUEvaluatorContext(new[] { g.ReferenceResponse }));
            contexts.Add(new F1EvaluatorContext(g.ReferenceResponse));
            contexts.Add(new EquivalenceEvaluatorContext(g.ReferenceResponse));
            contexts.Add(new CompletenessEvaluatorContext(g.ReferenceResponse));
        }
        if (!string.IsNullOrEmpty(g.Context))
            contexts.Add(new GroundednessEvaluatorContext(g.Context));

        await run.EvaluateAsync(messages, response, contexts);
    }
}

